"""Build self-contained ACR1 site from frozen evidence. No network required."""
from pathlib import Path
import shutil,json,hashlib,html,zipfile,os
from portable_metadata import normalize_registry, public_source_index
ROOT=Path(__file__).resolve().parents[1]
SOURCE=Path(os.environ.get('VOLLEY_ACR1_EXPORT',str(ROOT.parent/'validation/acr1')))
def copy_export(source,target):
 if source.is_file():shutil.copy2(source,target)
 elif not target.is_file():raise FileNotFoundError('Accepted source export required: '+str(target))
A=ROOT/'assets/acr1'; A.mkdir(exist_ok=True,parents=True)
# Keep reviewed camera, source and evidence-role metadata when rebuilding HTML.
REGISTER_PATH=A/'ASSET_REGISTER.json'
PRIOR_REGISTER=json.loads(REGISTER_PATH.read_text()) if REGISTER_PATH.is_file() else {}
for p in (SOURCE/'visuals/renders').glob('*'):
 if p.suffix in ['.jpg','.png','.json']: shutil.copy2(p,A/p.name)
for p in (SOURCE/'figures').glob('*'): shutil.copy2(p,A/p.name)
for p in (SOURCE/'mission/figures').glob('*'): shutil.copy2(p,A/p.name)
(A/'figures').mkdir(exist_ok=True)
for p in (SOURCE/'mission/figures').glob('*.png'):shutil.copy2(p,A/'figures'/p.name)
# Supplement figures retain exact public solver-export identities.
for record in json.loads((A/'supplements/SUPPLEMENT_FIGURES.json').read_text())['assets']:
 candidate=ROOT.parent/record['source_path'];target=ROOT.parent/record['path']
 if candidate.is_file():
  assert hashlib.sha256(candidate.read_bytes()).hexdigest()==record['source_sha256']
  copy_export(candidate,target)
 assert target.is_file()and hashlib.sha256(target.read_bytes()).hexdigest()==record['sha256']
for name in ['VIEW_PROVENANCE.json','MESH_PROVENANCE.json','VISUALS_MANIFEST.json','render_cad_views.py']:
 copy_export(SOURCE/'visuals'/name,A/name)
for name in ['MISSION_RESULTS.csv','MISSION_REPORT.md','MISSION_INPUTS.json','TARGETS.json','SELECTED_CASES.json','NATIVE_REPLAY_CHECKS.json']:
 copy_export(SOURCE/'mission'/name,A/name)
# Web source derivative: unchanged editable scene/mesh inputs; rendered stills served separately.
if not (ROOT/'downloads/VOLLEY_G5_ACR1_editable_scene.zip').exists():
 assert (SOURCE/'visuals/VOLLEY_G5_ACR1_scientific_views.blend').is_file(),'Provide VOLLEY_ACR1_EXPORT containing the accepted editable scene or retain the released scene ZIP.'
 with zipfile.ZipFile(ROOT/'downloads/VOLLEY_G5_ACR1_editable_scene.zip','w',zipfile.ZIP_DEFLATED,compresslevel=9) as archive:
  for p in sorted((SOURCE/'visuals').glob('*')):
   if p.is_file() and (p.suffix=='.json' or p.suffix=='.py' or p.suffix=='.blend' or p.name=='README.md'):
    archive.write(p,p.name)
  for p in sorted((SOURCE/'visuals/meshes').glob('*.json')):archive.write(p,'meshes/'+p.name)
  archive.writestr('WEB_PACKAGE_NOTE.txt','Source-only web derivative of the frozen ACR1 CAD views package. The scene, meshes, scripts and provenance files retain their original bytes. The original README describes the full distribution; this derivative serves accepted renders separately under docs/assets/acr1/. The scene contains all four editable views and its packed font. The rendering script reads meshes/ and creates renders/. No CAD or model evidence is changed.')
  archive.writestr('THIRD_PARTY_FONT_LICENSE.txt',(ROOT/'visual-source/THIRD_PARTY_FONT_LICENSE.txt').read_text())
for name in ['index','concept','evidence','evolution','work','docs','feeder-analysis','orbital-analysis','orbit-explorer']:
 old=ROOT/f'{name}.html'; archive=ROOT/f'historical-{name}.html'
 if old.exists() and not archive.exists():
  text=old.read_text(); text=text.replace('<body>','<body><aside class="archive-banner" style="padding:18px;background:#f6e7c4;color:#111">Historical page, retained as dated evidence. <a href="index.html" style="text-decoration:underline">Read the current ACR1 study</a>.</aside>',1);archive.write_text(text)
NAV=[('index.html','Home'),('concept.html','System'),('evidence.html','Evidence'),('orbital-analysis.html','Mission'),('films.html','Films'),('docs.html','Documents')]
def page(name,title,body,description='Commanded CubeSat deployment — computational design study. VOLLEY G5 ACR1.'):
 nav=''.join(f'<a href="{u}"'+(' aria-current="page"' if u==name else '')+f'>{t}</a>' for u,t in NAV)
 out=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{description}"><meta name="theme-color" content="#11161c"><meta property="og:title" content="VOLLEY · {title}"><meta property="og:image" content="https://aaaaaaaaaaaavm.github.io/VOLLEY/assets/acr1/ACR1_social_preview.png"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta name="twitter:card" content="summary_large_image"><title>VOLLEY · {title}</title><link rel="icon" href="assets/acr1/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="acr1.css"><script src="acr1.js" defer></script></head><body><a class="skip" href="#main">Skip to content</a><header class="nav"><div class="wrap"><a class="brand" href="index.html" aria-label="VOLLEY home">VOLLEY<span>COMMAND / RELEASE / REPEAT</span></a><nav aria-label="Main navigation">{nav}</nav></div></header><main id="main">{body}</main><footer><div class="wrap footer-grid"><div><a class="brand" href="index.html">VOLLEY</a><p>Commanded CubeSat deployment.<br>Computational design study · G5 ACR1</p></div><div><a href="docs.html">Documents & source</a><a href="assets/acr1/ASSET_REGISTER.json">Asset provenance</a><a href="accessibility.html">Accessibility</a><a href="updates.html">Study history</a></div><div><a href="https://github.com/aaaaaaaaaaaavm/VOLLEY">Engineering repository ↗</a><a href="https://github.com/aaaaaaaaaaaavm/VOLLEY/blob/main/LICENSING.md">Licensing ↗</a><p>Scientific figures and CAD renders identify their source.<br>No hardware or flight qualification is implied.</p></div></div></footer></body></html>'''
 (ROOT/name).write_text(out)
def section(k,t,c,cls=''):
 return f'<section class="{cls}"><div class="wrap"><div class="eyebrow">{k}</div><h2>{t}</h2>{c}</div></section>'
def fig(n,alt,cap):
 sizes={'polish/assembly_hero.webp':(2000,1250),'polish/feeder_detail_annotated.webp':(1800,1650),'polish/operating_sequence.webp':(2000,900)}
 width,height=sizes.get(n,(2800,2100));full=n.removesuffix('.webp')+'.png' if n.endswith('.webp') else n
 return f'<figure><a href="assets/acr1/{full}" aria-label="Open full size: {alt}"><img src="assets/acr1/{n}" alt="{alt}" loading="lazy" width="{width}" height="{height}"></a><figcaption>{cap}</figcaption></figure>'
def card(title,copy,url,label='Inspect evidence'):
 return f'<article class="card"><h3>{title}</h3><p>{copy}</p><a class="text-link" href="{url}">{label} <span aria-hidden="true">↗</span></a></article>'
def hero(k,t,p):return f'<div class="page-intro wrap"><div class="eyebrow">{k}</div><h1>{t}</h1><p class="lead">{p}</p></div>'
EXTENDED_ENGINEERING_SECTION = '<section id="extended-engineering"><div class="wrap"><div class="eyebrow">Extended engineering analyses</div><h2>From native dynamics to first measurements.</h2><div class="grid two"><figure><a href="assets/acr1/supplements/SD01_modes.png"><img src="assets/acr1/supplements/SD01_modes.png" width="2652" height="962" loading="lazy" alt="Forty native elastic chassis modes and a normalized numerical mode field."></a><figcaption>CalculiX model output · SD01 free-free bare-chassis modes. Mode shapes are normalized for display.</figcaption></figure><figure><a href="assets/acr1/supplements/release_departure_histories.png"><img src="assets/acr1/supplements/release_departure_histories.png" width="1800" height="1260" loading="lazy" alt="Native payload release-speed and angular-rate histories for nominal and perturbed local contact cases."></a><figcaption>MuJoCo model output · local departure/contact sensitivities. Contact parameters are declared model inputs.</figcaption></figure></div><div class="grid two"><article class="card"><h3>Structural dynamics</h3><p>Forty elastic modes, finite forcing, phase-dependent normal reaction and conditional clearance.</p><a class="text-link" href="https://github.com/aaaaaaaaaaaavm/VOLLEY/blob/main/docs/ACR1_STRUCTURAL_DYNAMICS.md">Methods and native results ↗</a></article><article class="card"><h3>Release and arrest</h3><p>Forty-two native runs with local egress, contact/refinement and keeper-catch sensitivity.</p><a class="text-link" href="https://github.com/aaaaaaaaaaaavm/VOLLEY/blob/main/docs/ACR1_RELEASE_DYNAMICS.md">Histories and interpretation ↗</a></article><article class="card"><h3>Thermal operating envelope</h3><p>CAD-based radiation, repeated duty, regulated host heat paths and a separately identified voltage-derated source.</p><a class="text-link" href="https://github.com/aaaaaaaaaaaavm/VOLLEY/blob/main/docs/ACR1_THERMAL_ENVIRONMENT.md">Conditions and computed limits ↗</a></article><article class="card"><h3>Lunar campaign</h3><p>Finite host authority, release policy, covariance, native orbit lifetimes and independent engine-only disposal.</p><a class="text-link" href="https://github.com/aaaaaaaaaaaavm/VOLLEY/blob/main/docs/PROGRAMME_STUDIES_ACR1.md">Campaign and resource study ↗</a></article></div><p><a href="https://github.com/aaaaaaaaaaaavm/VOLLEY/blob/main/docs/ACR1_FIRST_TEST_PACKAGE.md">Subsequent Gen6 first-test packet: procedures, provisional fixture STEP and predeclared acceptance criteria ↗</a></p><p>These separately identified supplements preserve the accepted ACR1 core and ED1 document identities. Numerical output, proposed fixture geometry and physical measurements are distinct evidence classes.</p></div></section>'
source='https://github.com/aaaaaaaaaaaavm/VOLLEY/tree/main/validation/acr1'
academic_edition='https://github.com/aaaaaaaaaaaavm/VOLLEY-thesis/tree/main/editions/ED3'
academic_raw='https://raw.githubusercontent.com/aaaaaaaaaaaavm/VOLLEY-thesis/main/editions/ED3'
academic_handoff='https://github.com/aaaaaaaaaaaavm/VOLLEY-thesis/blob/main/editions/ED3/SPEAKER_NOTES.md'
academic_note='<p>The latest report and presentation are <b>academic edition ED3, 27 October 2026</b>: 58 pages and 17 slides with a 900-second two-speaker route. The nine-page IEEE-formatted manuscript remains ED1 and unsubmitted. ED1 report/deck files retain their original identities in the academic capture.</p><p>Each edition preserves its report, presentation and source identities. Subsequent research is versioned separately.</p>'

PARTIAL_OCCUPANCY_SECTION = '<section id="partial-occupancy"><div class="wrap"><div class="eyebrow">26 October / mission supplement</div><h2>One machine, different manifest sizes.</h2><p>Two- and four-payload campaigns extend the retained twelve-payload reference: 28 finite-force candidates and 17 native Orekit replays, with full hardware mass retained.</p><figure><a href="assets/acr1/supplements/partial_occupancy_propellant.png"><img src="assets/acr1/supplements/partial_occupancy_propellant.png" width="2220" height="1050" loading="lazy" alt="Host propellant across two, four and twelve payloads for uniform and alternating target families at 5 N allocated authority."></a><figcaption>Computed host propellant at 5 N allocated authority for two, four and twelve same-size 3U payloads. Full retained hardware is counted at every occupancy. The alternating family has no tested ACR1 pass at 1 N; blank points denote no tested pass, not zero fuel. These are numerical mission comparisons, not physical delivery accuracy.</figcaption></figure><p><a href="https://github.com/aaaaaaaaaaaavm/VOLLEY/blob/main/validation/acr1_partial_occupancy/REPORT.md">Methods, full-state results, native replay and resource comparison ↗</a></p></div></section>'
EXTENDED_ENGINEERING_SECTION += PARTIAL_OCCUPANCY_SECTION


POLISH_MECHANISM_SECTION = section('Feed and custody','Inspect the mechanism.', '<div class="grid two">'+fig('polish/feeder_detail_annotated.webp','Isolated guided lead-screw and pusher cell with four annotated source-part locations.','CAD-derived Blender detail · south bank, level 5. Payload envelope and fixed channel frame hidden; drive solids are catalog envelopes.')+'<div><h3>Guided transfer</h3><ol><li>10 × 2 lead-screw reference.</li><li>Motor/gear and brake reference envelopes.</li><li>Guided pusher frame.</li><li>Guide shaft.</li></ol><p>The screw drives a guided pusher frame; guide shafts maintain the represented transfer direction. The indexed lift receives the payload on its captive pallet.</p><p>Only display materials, camera and visibility differ from the frozen CAD source. The smooth screw reference does not show a manufactured thread.</p></div></div>'+fig('polish/operating_sequence.webp','Four frozen CAD poses: home, captured, handoff and clear. Other storage cells and host ladder omitted for clarity.','Four nominal CAD poses · other banks and host ladder hidden; distant rail cropped. This board shows feed/custody states before launch, not measured motion.')+'<p><a href="assets/acr1/polish/POLISH_PROVENANCE.json">Cameras, visibility and unchanged mesh/pose identities</a> · <a href="assets/acr1/polish/README_DELTA.md">Editable source and reproduction</a></p>')

